 const saveFile=()=>{if(!fileDraft||fileConflict||!can('projects.save'))return;setFileDrafts(prev=>({...prev,[currentFileKey]:{...prev[currentFileKey],submitted:fileDraft.text}}));run('projects.save',{projectId:state.projectId,path:state.filePath,version:fileDraft.version,content:fileDraft.text});};
 const copyText=async(textToCopy:string)=>{try{if(!navigator.clipboard?.writeText)throw new Error('当前无法直接复制，请选择文字后复制。');await navigator.clipboard.writeText(textToCopy);toast('已复制');}catch(error){const message=error instanceof Error?error.message:'复制未完成，请选择文字后复制。';setLocalError(message);toast.error(message);throw error;}};
 const closeModelPicker=()=>{setModelPickerOpen(false);modelRequest.current++;modelSelectionRequested.current=false;setModelLoading(false);setModelReview(null)};
 const openModelPicker=()=>{setModelPickerOpen(true);setModelReadError('');setModelReview(null);modelSelectionRequested.current=false;if(!can('models.snapshot'))return;const request=++modelRequest.current;setModelLoading(true);void act('models.snapshot').then(value=>{if(modelRequest.current===request)setModelDirectory(obj(value))}).catch(error=>{if(modelRequest.current===request)setModelReadError(error.message)}).finally(()=>{if(modelRequest.current===request)setModelLoading(false)});};
 const catalog=obj(modelDirectory||state.modelConnections||state.ownerSnapshots?.models);const catalogModels=asArray<Json>(catalog.models);const currentModelId=state.modelRoute==='account'?`account:${state.modelName}`:String(state.modelName||'');
 const modelSelectionLocked=!!state.activeTaskId||!!state.chatBusy||!!state.chatSubmitting||!!state.phoneSubmitting||!!state.modelSaving||!!state.modelTesting||!!state.modelSelectionBusy||modelSelectPending;
