 const reviewModelSelection=(modelId:string)=>{if(!modelSelectionSupported||modelSelectionLocked)return;modelSelectionRequested.current=true;const request=++modelRequest.current;setModelLoading(true);setModelReadError('');setModelReview(null);void act('models.review',{modelId}).then(value=>{if(modelRequest.current===request)setModelReview(obj(value))}).catch(error=>{if(modelRequest.current===request)setModelReadError(error.message)}).finally(()=>{if(modelRequest.current===request)setModelLoading(false)});};
